{"cards": [{"node_code": "N_ad56e156c3fc80f4", "definition": "指港口工程前期阶段，为确定建设规模、论证技术经济可行性而开展的货源、运输量、投资估算及效益分析等专项调查工作。", "boundary": "本节点聚焦于港口建设前的“经济可行性”数据获取。边界在于区分“经济调查”与“水文/地质勘测”（侧重自然条件）、“港口设计”（侧重工程方案）。若内容涉及建成后的运营经济分析或宏观港口经济政策，不属于本节点，应归入水路运输经济或管理相关节点。", "includes": ["港口吞吐量预测与货源调查", "港口建设投资估算与财务评价", "港口建设必要性论证资料收集"], "excludes": ["港口建成后的运营成本控制与经济效益评估", "宏观区域港口布局规划的经济分析", "纯财务审计或会计处理"], "sibling_distinctions": [{"other_code": "N_8673dee329c997da", "rule": "本节点侧重社会经济数据（货量、投资），兄弟节点侧重自然物理数据（岩土、地基）。"}, {"other_code": "N_981e2de5619b4849", "rule": "本节点侧重经济可行性，兄弟节点侧重通航条件（水深、流速）等自然水文数据。"}, {"other_code": "N_26e1535d2a7dc3f5", "rule": "本节点为设计提供经济依据，兄弟节点为设计提供工程参数；前者是输入条件，后者是工程方案。"}], "cross_boundary_rule": "若内容涉及利用经济调查数据进行具体的码头规模设计，主挂载本节点（作为数据源）；若侧重设计方法本身，主挂载港口设计。"}, {"node_code": "N_8673dee329c997da", "definition": "指港口工程前期，为查明建设场地的岩土工程条件、地基承载力及稳定性而进行的地质勘探、取样及室内/野外试验工作。", "boundary": "本节点聚焦于港口建设场地的“岩土工程”属性。边界在于区分“地质勘测”与“地形测量”（侧重地表形态）、“水文勘测”（侧重水体运动）。若内容涉及海洋地质或海底地形，需结合具体语境，若侧重地基处理则归入本节点。不包括纯地质科学研究或矿产资源勘探。", "includes": ["港口场地工程地质勘察与钻探", "岩土物理力学性质试验与地基承载力分析", "不良地质现象（如软土、岩溶）调查与处理建议"], "excludes": ["纯地质构造研究或古地理研究", "矿产资源勘探与开采", "港口建成后的地基沉降监测与维护"], "sibling_distinctions": [{"other_code": "N_153c3a45998fbb5a", "rule": "本节点侧重地下岩土体性质，兄弟节点侧重地表及水下地形地貌形态。"}, {"other_code": "N_981e2de5619b4849", "rule": "本节点侧重固体介质（岩土），兄弟节点侧重流体介质（水）的运动规律。"}], "cross_boundary_rule": "若内容涉及地质数据在码头结构设计中的应用，主挂载本节点（数据获取）；若侧重结构计算模型，主挂载港口设计。"}, {"node_code": "N_981e2de5619b4849", "definition": "指港口工程前期，为确定通航条件、码头前沿水深及防波堤设计参数而进行的水深、流速、波浪、潮汐等水文要素观测与分析工作。", "boundary": "本节点聚焦于港口水域的“水文”特性。边界在于区分“水文勘测”与“气象勘测”（侧重风、雨、气温）、“地质勘测”（侧重岩土）。若内容涉及航道整治的水文计算，归入本节点。不包括纯海洋学科学研究或长期气候趋势预测。", "includes": ["港口水域水深、流速、流向观测", "波浪、潮汐、潮流及泥沙运动规律分析", "港口设计水位与通航条件论证"], "excludes": ["港口气象要素（风、雾、气温）观测", "港口地质与岩土工程勘察", "港口建成后的水文监测与航道维护疏浚"], "sibling_distinctions": [{"other_code": "N_5ef1bf86e6f46884", "rule": "本节点侧重水体运动（流、波、潮），兄弟节点侧重大气现象（风、雨、温）。"}, {"other_code": "N_8673dee329c997da", "rule": "本节点侧重流体（水）特性，兄弟节点侧重固体（岩土）特性。"}], "cross_boundary_rule": "若内容涉及水文数据在防波堤或码头设计中的应用，主挂载本节点（数据获取）；若侧重结构抗浪设计，主挂载港口设计。"}]}
